Here is the commit message:
arm64/gcs: Fix error handling in
 arch_set_shadow_stack_status()

alloc_gcs() returns an error-encoded pointer on failure, which comes
from do_mmap(), not NULL.

The current NULL check fails to detect errors, which could lead to using
an invalid GCS address.

Use IS_ERR_VALUE() to properly detect errors, consistent with the
check in gcs_alloc_thread_stack().

Fixes: b57180c75c7e ("arm64/gcs: Implement shadow stack prctl() interface")
Reviewed-by: Mark Brown <broonie@kernel.org>
Signed-off-by: Breno Leitao <leitao@debian.org>
Signed-off-by: Will Deacon <will@kernel.org>

Here is the root cause:
The bug is due to incorrect error checking after calling alloc_gcs() in arch_set_shadow_stack_status(). alloc_gcs() returns an error-encoded pointer (e.g., -ENOMEM cast to unsigned long) on failure, but the original code checked for NULL (if (!gcs)), which fails to detect error values because they are non-zero. This oversight allows an invalid GCS address to be used, potentially causing memory corruption or security issues.

Here is the patch:

 int arch_set_shadow_stack_status(struct task_struct *task, unsigned long arg)
 {
 	unsigned long gcs, size;
 	int ret;

 	if (!system_supports_gcs())
 		return -EINVAL;

 	if (is_compat_thread(task_thread_info(task)))
 		return -EINVAL;

 	/* Reject unknown flags */
 	if (arg & ~PR_SHADOW_STACK_SUPPORTED_STATUS_MASK)
 		return -EINVAL;

 	ret = gcs_check_locked(task, arg);
 	if (ret != 0)
 		return ret;

 	/* If we are enabling GCS then make sure we have a stack */
 	if (arg & PR_SHADOW_STACK_ENABLE &&
 	    !task_gcs_el0_enabled(task)) {
 		/* Do not allow GCS to be reenabled */
 		if (task->thread.gcs_base || task->thread.gcspr_el0)
 			return -EINVAL;

 		if (task != current)
 			return -EBUSY;

 		size = gcs_size(0);
 		gcs = alloc_gcs(0, size);
-		if (!gcs)
-			return -ENOMEM;
+		if (IS_ERR_VALUE(gcs))
+			return gcs;

 		task->thread.gcspr_el0 = gcs + size - sizeof(u64);
 		task->thread.gcs_base = gcs;
 		task->thread.gcs_size = size;
 		if (task == current)
 			write_sysreg_s(task->thread.gcspr_el0,
 				       SYS_GCSPR_EL0);
 	}

 	task->thread.gcs_el0_mode = arg;
 	if (task == current)
 		gcs_set_el0_mode(task);

 	return 0;
 }



